import AVFoundation
import Foundation
import os

/// Call sound cues for the iOS / iPadOS / macOS / watchOS clients
/// (S-3-A-sounds).
///
/// Sound files live in the app bundle under `Lakko/Resources/Sounds/`
/// — generated by `tools/audio/synth-sounds.sh` from pure sine
/// tones, no third-party samples. xcodegen's `path: Lakko`
/// recursion in `project.yml` picks them up automatically.
///
/// Two play modes:
///
/// - `playOnce(_:)` — fire-and-forget short cue (`join` /
///   `leave` / `error`).
/// - `startLoop(_:)` / `stopLoop(_:)` — repeating cue
///   (`ringtone-incoming` / `ringback-outgoing`). `numberOfLoops
///   = -1` on the cached `AVAudioPlayer` keeps it going until
///   explicitly stopped.
///
/// ## CallKit interaction
///
/// `CXProviderConfiguration.ringtoneSound` is the right knob
/// for the system-level incoming-call ringtone — that's set in
/// `LakkoApp` / `CallKitProvider` once we wire CallKit in
/// 3a-pod-followup. This controller handles *in-app*
/// cues that play **after** the call has been answered (join,
/// leave, error, ringback while waiting for the callee).
///
/// ## Silent-mode politeness
///
/// We honour the system mute switch by routing through the
/// `.ambient` audio session category. That category obeys the
/// physical ring/silent switch — exactly the behaviour the
/// user expects from non-essential UI cues. Critical CallKit
/// ringtones use the `.playAndRecord` category which ignores
/// the switch; that path is owned by `CXProvider`, not us.
///
/// ## Thread safety
///
/// `AVAudioPlayer` is **not** thread-safe. Every method on
/// this controller dispatches to the main queue if invoked
/// off-main, so call sites need not worry. The
/// `@MainActor` annotation makes that statically enforceable.
/// Minimal `ObservableObject` wrapper around [`CallSoundController`].
///
/// SwiftUI's `@StateObject` requires its value to conform to
/// `ObservableObject`. The controller itself does not publish
/// any state — sound playback is a side-effect, not a model —
/// so we wrap it in a tiny ObservableObject that holds the
/// controller as an immutable property. The wrapper exists
/// purely so `CallScreen` can keep one controller alive across
/// view reloads via `@StateObject` rather than reconstructing
/// it on every render.
@MainActor
public final class CallSoundsObservable: ObservableObject {
    public let controller: CallSoundController

    /// `controller` defaults to `nil` because Swift evaluates
    /// default expressions outside the surrounding actor
    /// context — passing `CallSoundController()` directly
    /// would call a `@MainActor` initializer from a
    /// nonisolated default-expression context.
    public init(controller: CallSoundController? = nil) {
        self.controller = controller ?? CallSoundController()
    }
}

@MainActor
public final class CallSoundController {

    /// Pinned set of cue names. Same identifiers as the web
    /// (`SoundName` in `CallSoundController.ts`) and Android
    /// controllers — keeping the names in lockstep lets the
    /// wiring layer share a single trigger map across
    /// platforms.
    public enum SoundName: String, CaseIterable {
        case ringtoneIncoming = "ringtone-incoming"
        case ringbackOutgoing = "ringback-outgoing"
        case join = "join"
        case leave = "leave"
        case error = "error"

        /// Loops until explicitly stopped.
        fileprivate var isLooping: Bool {
            switch self {
            case .ringtoneIncoming, .ringbackOutgoing:
                return true
            case .join, .leave, .error:
                return false
            }
        }
    }

    private static let log = Logger(
        subsystem: "me.lakko.calls",
        category: "sound-controller"
    )

    private var cache: [SoundName: AVAudioPlayer] = [:]
    private let volume: Float

    /// `volume` is a uniform multiplier in `[0.0, 1.0]`. The
    /// AAC encoding targets a comfortable −10 dB peak, so the
    /// OS volume slider stays the user-facing knob.
    public init(volume: Float = 1.0) {
        self.volume = max(0.0, min(1.0, volume))
        Self.configureAudioSession()
    }

    deinit {
        // Stopping individual players on dealloc is a courtesy
        // — they'd be torn down by ARC anyway, but stopping
        // first cuts the speaker without a fade-out artifact.
        for player in cache.values {
            player.stop()
        }
    }

    /// Play `name` once. Calling this while a previous
    /// fire-and-forget of the same cue is still ringing
    /// rewinds the player so the second invocation surfaces
    /// audibly (matches the web semantics).
    public func playOnce(_ name: SoundName) {
        guard let player = makePlayer(for: name) else { return }
        player.currentTime = 0
        player.numberOfLoops = 0
        player.volume = volume
        if !player.play() {
            Self.log.warning("playOnce(\(name.rawValue)) failed")
        }
    }

    /// Start `name` looping. No-op if the same cue is
    /// already playing — keeps the pattern (2 s on / 4 s
    /// off for `ringtone-incoming`) steady.
    public func startLoop(_ name: SoundName) {
        guard name.isLooping else {
            Self.log.warning("startLoop on non-looping cue \(name.rawValue)")
            return
        }
        guard let player = makePlayer(for: name) else { return }
        if player.isPlaying { return }
        player.numberOfLoops = -1
        player.volume = volume
        if !player.play() {
            Self.log.warning("startLoop(\(name.rawValue)) failed")
        }
    }

    /// Stop `name`'s loop, rewinding so a subsequent
    /// `startLoop` begins cleanly at the burst boundary.
    public func stopLoop(_ name: SoundName) {
        guard let player = cache[name] else { return }
        player.stop()
        player.currentTime = 0
    }

    /// Stop every active cue (loops + one-shots). Called on
    /// `endCall()` / view dismissal.
    public func stopAll() {
        for player in cache.values {
            player.stop()
            player.currentTime = 0
        }
    }

    // MARK: - Internals

    private func makePlayer(for name: SoundName) -> AVAudioPlayer? {
        if let cached = cache[name] {
            return cached
        }
        // Resources land in the main bundle. xcodegen's
        // `Resources/Sounds/*.m4a` recursion delivers them
        // under the `Sounds/` subdirectory.
        guard
            let url = Bundle.main.url(
                forResource: name.rawValue,
                withExtension: "m4a",
                subdirectory: "Sounds"
            )
            ?? Bundle.main.url(
                forResource: name.rawValue,
                withExtension: "m4a"
            )
        else {
            Self.log.error("missing bundle resource \(name.rawValue).m4a")
            return nil
        }
        do {
            let player = try AVAudioPlayer(contentsOf: url)
            player.prepareToPlay()
            cache[name] = player
            return player
        } catch {
            Self.log.error("AVAudioPlayer init failed for \(name.rawValue): \(error.localizedDescription)")
            return nil
        }
    }

    /// Configure the audio session so that:
    /// - cues honour the silent switch (`.ambient` category),
    /// - other audio (music, podcasts) ducks rather than
    ///   stops when we play a cue (`.mixWithOthers`,
    ///   `.duckOthers`).
    ///
    /// This runs from `init`, and the controller is a
    /// `@StateObject` on both call screens — so it runs again
    /// on every presentation, i.e. once per call.
    ///
    /// It used to set the category straight on
    /// `AVAudioSession.sharedInstance()`, and the note here
    /// claimed CallKit would override it with
    /// `.playAndRecord` once a call began. That reasoning was
    /// wrong twice over. `IncomingCallPresentation.decide`
    /// returns `.inApp` whenever the app is active, so a call
    /// answered in the open app never reaches CallKit at all
    /// and nothing overrides anything. And `.ambient` cannot
    /// record, so the second and later calls in a process came
    /// up with a silent microphone — see ``CallAudioSession``
    /// for the full mechanism and the evidence.
    ///
    /// Now it goes through ``CallAudioSession``, which holds
    /// `RTCAudioSession`'s lock and declines to touch the
    /// session at all while a call owns it.
    private static func configureAudioSession() {
        CallAudioSession.applyCuePosture()
    }
}
